   f=z[z.tipo_perfil==kind];a.fill_between(f.lag,f.sim_low*.1,f.sim_high*.1,color='#b9cbdc',alpha=.5,label='Banda simultânea aproximada');a.fill_between(f.lag,f.low*.1,f.high*.1,color='#2b657b',alpha=.18,label='IC pontual');a.plot(f.lag,f.estimate*.1,color='#174f64',marker='o',ms=3);a.axhline(0,color='#111',lw=.8);a.set(title=title,xlabel='Meses',ylabel='Pontos percentuais / +10 p.p. cobertura municipal');a.xaxis.set_major_locator(MaxNLocator(integer=True))
