def summary():
 r=tables('principais');cr=tables('cr2');pl=tables('placebos');inter=tables('interacao')
 counts={}
 for infer in ['cluster','boot','dk']:
  counts[infer]={'acumulado':int((r['q_global_acumulado_'+infer+'_p']<.05).sum()),'conjunto':int((r['q_global_joint_'+infer+'_p']<.05).sum())}
 cm=cr[cr.design.eq('main')];counts['cr2']={'acumulado':int(((cm.endpoint=='acumulado')&(cm.q_global_p<.05)).sum()),'conjunto':int(((cm.endpoint=='joint')&(cm.q_global_p<.05)).sum())}
 stable=r[(r.q_global_acumulado_boot_p<.05)&(r.q_global_acumulado_cluster_p<.05)&(r.q_global_acumulado_dk_p<.05)]
 crkeys=set(zip(cm.loc[(cm.endpoint=='acumulado')&(cm.q_global_p<.05),'periodo'],cm.loc[(cm.endpoint=='acumulado')&(cm.q_global_p<.05),'coluna']))
 stable=stable[[ (p,c) in crkeys for p,c in zip(stable.periodo,stable.coluna)]]
 return counts,stable

def write_results():
 r=tables('principais');cr=tables('cr2');s=tables('suporte');pl=tables('placebos');it=tables('interacao');loo=tables('onda_frio_leave_out');nat=tables('nacional');counts,stable=summary()
 cold=r[r.coluna=='tipo_onda_de_frio'];cips=tables('cips');lines=['# Revisão metodológica DLM — resultados','',f'46 de 48 cenários estimados. Horizonte 0–12; cobertura municipal relativa; seleção J3/J4 por BIC. Resultados históricos preservados em dlm/. Protocolo prévio no commit 1641dfd. Nenhum Granger reestimado e nenhum SARIMAX executado.','', '## A. Problemas anteriores','K curto selecionado em DLM irrestrito não mede duração. Suporte esparso, 27 clusters nominais com contribuição desigual, ausência de placebos e comparação de recortes sobrepostos limitavam a interpretação. Os testes antigos exigiam o resultado de Onda de Frio; novos testes não exigem significância.','', '## B. Ajustes implementados','Auditoria UF-mês exata; ocorrências municipais auditáveis; cobertura; classificação por COBRADE; suporte e N_eff; splines; C(h); bandas condicionais; placebos; interação; inferência CR2/WCR/DK; multiverse finita; ponderação fixa; nacional complementar.','', '## C. Especificação principal','ΔI em pp; C_prop em escala 0–1; K12; spline natural J3/4; UF FE e mês-ano FE; não ponderado; CR1S, CR2+Satterthwaite/HTZ, WCR11 e DK12; BH global48 separado por endpoint/inferência. Não há seleção por p.','', '## D. Exposição','40339 registros; 40238 chaves municipais únicas; 101 repetições da chave; nenhuma duplicata exata. Cobertura significa municípios com registros, não população/área ou intensidade. Mudança +10 pp de cobertura multiplica coeficiente por 0,1. A/B/C são sensibilidades, com estimandos/unidades distintos. 13310 em Chuvas Intensas exige ressalva nome/código; 14140 não permite isolar onda de calor de baixa umidade.','', '## E. Defasagens por tipo','K12 compara janelas sem impor curvas iguais. Horizontes ex ante K6 para súbitos e robustez K6 para persistentes. A métrica h90 de massa absoluta é descritiva, não último lag significativo nem duração causal. Perfis sem suporte e estabilidade ficam inconclusivos.','', '## F. Resultados gerais',json.dumps(counts,ensure_ascii=False),'','Rejeições BH global48 por inferência (acumulado/conjunto). Concordância nos quatro métodos é necessária, mas insuficiente para robustez substantiva.',f'Acumulados simultaneamente ajustados em todos os quatro: {len(stable)}.','']
 lines += ['## G. Grupos e agregados analíticos',r[r.nivel.isin(['Total','Grupo','Analítica'])][['periodo','exposicao','acumulado_cluster_estimate','q_global_acumulado_cluster_p','q_global_acumulado_boot_p']].to_markdown(index=False),'','## H. Tipologias',r[r.nivel=='Tipologia'][['periodo','exposicao','acumulado_cluster_estimate','q_global_acumulado_cluster_p','q_global_acumulado_boot_p','q_global_joint_boot_p']].to_markdown(index=False),'','## I. Onda de Frio']
 for row in cold.itertuples():
  cc=cr[(cr.design=='main')&(cr.periodo==row.periodo)&(cr.coluna==row.coluna)&(cr.endpoint=='acumulado')].iloc[0];ss=s[(s.coluna==row.coluna)&(s.periodo==row.periodo)&(s.medida=='C_prop')].iloc[0]
  lines += [f'{row.periodo}: C12={row.acumulado_cluster_estimate:.6g} pp/unidade; cluster p={row.acumulado_cluster_p:.6g}; WCR p={row.acumulado_boot_p:.4f}; DK p={row.acumulado_dk_p:.6g}; CR2 p={cc.p:.6g}, df={cc.df:.3f}; N_eff cobertura={ss.n_eff:.3f}; top1={ss.top1:.1%}; top2={ss.top2:.1%}.']
 lines+=['','**Classificação do sinal positivo pré anterior: não robusto.** A versão principal revisada não o reproduz; suporte fortemente concentrado. Não comparar magnitudes brutas C_prop e log1p(A). Rastreio A/K3 mostra o impacto isolado de ampliar inferência na medida histórica. As retiradas de UFs incluem cenários que perdem suporte mínimo e não devem ser promovidos a especificações principais.','',loo[['periodo','retirada','status','n_eff','acumulado_cluster_estimate','acumulado_cluster_low','acumulado_cluster_high','acumulado_cluster_p']].to_markdown(index=False),'','## J. Placebos',f'Rejeições BH leads: cluster={int((pl.q_global_joint_cluster_p<.05).sum())}; WCR={int((pl.q_global_joint_boot_p<.05).sum())}; CR2={int(((cr.design=="leads")&(cr.endpoint=="joint")&(cr.q_global_p<.05)).sum())}. Placebos não comprovam exogeneidade quando não rejeitam.','', '## K. Pré versus pós',it[['exposicao','pre_cluster_estimate','pos_cluster_estimate','diferenca_cluster_estimate','q_global_joint_boot_p']].to_markdown(index=False),'Pós é fev/2020 em diante. A hipótese conjunta de γ e a diferença acumulada são perguntas diferentes. Janela da pandemia exclui respostas, não necessariamente todas exposições defasadas.','', '## L. Poucos clusters','CR2 usa df Satterthwaite do contraste, não G−1 nem N_eff. Concentração pode produzir df efetivo muito baixo e grande discordância. Wild bootstrap não corrige automaticamente poucos estados informativos. Bandas baseadas em cluster são aproximações condicionais e não certificam categorias concentradas.','', '## M. Robustez','Todas as sensibilidades estão em multiverse.csv; inferência não foi selecionada pelo menor p. CD é diagnóstico aproximado: FE temporais induzem restrições transversais; não usar p CD como certificação. Autocorrelação permanece limitação em alguns cenários.','', '## N. Painel versus nacional','Há 4 efeitos acumulados diretos e 10 perfis conjuntos após BH/HAC nesta análise complementar. Os 4 acumulados são Inundações, Onda de Calor/Baixa Umidade e Onda de Frio no total, e o agregado Natural não diretamente climático no pré. Seus diagnósticos Ljung–Box12 não rejeitam; isso não prova adequação, elimina confundimento ou certifica estabilidade. Não apagar essas associações por não coincidirem com o painel.',nat[['periodo','exposicao','p_proprio','acumulado_direto','q_global_p_acumulado','q_global_p_conjunto','ljungbox12_p']].to_markdown(index=False),'O painel remove variação nacional comum; o nacional mantém essa variação e é vulnerável a confundimento agregado. Soma direta do componente exposição não é multiplicador total em modelo com lags próprios; recursão dinâmica é descritiva, sem bandas conjuntas nesta extensão.','', '## O. Granger','A etapa15 encontrou Granizo total exploratório sensível a HAC/especificação. Granger usa séries nacionais diferentemente transformadas e testa informação precedente. DLM estima associação relativa UF-mês. Não exigir concordância entre métodos.','', '## P. Implicações para SARIMAX','Não executado. Usar futura validação temporal fora da amostra, controles e regressoras selecionados por mecanismo/disponibilidade e não pelo menor p nesta revisão. Evitar selecionar Onda de Frio por resultado histórico.','', '## Q. Atualização do TCC','1. Dados: atualizar cobertura 2013–2024, contagem e taxonomia nome/código.','2. Metodologia DLM: ΔI, exposição territorial, estimando TWFE e ponderado, spline K12, contrastes/covariâncias e bandas.','3. Inferência: CR2/Satterthwaite/HTZ, WCR11, DK, famílias BH48/24 e limitações de suporte.','4. Períodos: recortes sobrepostos descritivos; interação formal e definição de Pós.','5. Resultados: substituir afirmação de Onda de Frio robusta; reportar divergências e leave-outs.','6. Discussão: não atribuir contagens ou associações à mudança climática antropogênica; exposição registrada não mede causalidade climática.','7. Nacional: razão de somas, dinâmica própria, soma direta versus resposta recursiva; limitações de amostra/diagnósticos.','8. Conclusão: ausência de perfil robusto não demonstra ausência de impactos; manter resultados não estimáveis/inconclusivos.','', '## Estacionariedade em painel',cips.to_markdown(index=False),'','## Limitações adicionais','Exposição retrospectiva não garante informação disponível em tempo real; cadastro municipal não mede área/população; modelagem linear homogênea por UF, splines podem suavizar reversões abruptas; seleção de J e amostras pequenas aumentam incerteza. ICs e bandas não incorporam incerteza de mensuração da exposição. Rejeição conjunta pode ocorrer com soma próxima de zero.']
 (ROOT/'docs/dlm_revisao_resultados.md').write_text('\n\n'.join(lines),encoding='utf-8')
 save(pd.DataFrame([dict(inferencia=k,**v) for k,v in counts.items()]),'resumo_fdr')
 return '\n\n'.join(lines)

def dynamics_support():
 d=load_panel();e=get_exps();r=tables('principais');p=tables('perfis');rows=[];srows=[]
 for rr in r.itertuples():
  keep=d.data_base.between(*PERIODS[rr.periodo]);q=lag_frame(d.loc[keep],e[rr.coluna]['C_prop'][keep]);f=model(q,basis(12,rr.J));qq=f['q'];positive=qq[[f'x{k}' for k in range(13)]].gt(0).any(axis=1)
  lev=np.array([np.trace(f['bread']@(f['X'][qq.uf.eq(uf)].T@f['X'][qq.uf.eq(uf)])) for uf in sorted(qq.uf.unique())]);lev/=lev.sum()
  srows.append(dict(periodo=rr.periodo,coluna=rr.coluna,ufs_com_exposicao_na_janela=int(qq.loc[positive,'uf'].nunique()),uf_mes_com_exposicao_na_janela=int(positive.sum()),neff_alavancagem=float(1/(lev@lev)),top_alavancagem=float(lev.max()),rank=f['rank']))
  beta=p[(p.periodo==rr.periodo)&(p.coluna==rr.coluna)&(p.tipo_perfil=='beta')].sort_values('lag');v=beta.estimate.to_numpy();mass=abs(v);h=int(np.searchsorted(np.cumsum(mass),.9*mass.sum())) if mass.sum()>0 else 0
  shares=[mass[:3].sum()/mass.sum(),mass[3:7].sum()/mass.sum(),mass[7:].sum()/mass.sum()]
  shape='compensação / reversão descritiva' if v.min()<0<v.max() else ('positivo descritivo' if v.min()>=0 else 'negativo descritivo')
  rows.append(dict(periodo=rr.periodo,coluna=rr.coluna,exposicao=rr.exposicao,h90_massa_absoluta=h,massa_0_2=shares[0],massa_3_6=shares[1],massa_7_12=shares[2],formato_descritivo=shape,classificacao_temporal='inconclusivo: sem confirmação após FDR robusta',interpretacao='h90 não é duração de efeito; depende da spline e da magnitude pontual'))
 save(pd.DataFrame(rows),'horizontes_descritivos');save(pd.DataFrame(srows),'suporte_design')

