def classify():
 r=tables('principais');diag=tables('diagnosticos');s=tables('suporte');cr=tables('cr2');leads=tables('placebos');rows=[]
 for v in r.itertuples():
  q=diag[(diag.periodo==v.periodo)&(diag.coluna==v.coluna)].iloc[0];u=s[(s.periodo==v.periodo)&(s.coluna==v.coluna)&(s.medida=='C_prop')].iloc[0]
  joint=cr[(cr.design=='main')&(cr.periodo==v.periodo)&(cr.coluna==v.coluna)&(cr.endpoint=='joint')].iloc[0]
  cum=cr[(cr.design=='main')&(cr.periodo==v.periodo)&(cr.coluna==v.coluna)&(cr.endpoint=='acumulado')].iloc[0]
  pl=leads[(leads.periodo==v.periodo)&(leads.coluna==v.coluna)].iloc[0]
  diagnosis='com ressalvas'
  if u.status=='exposição altamente concentrada' or joint.status_inferencia!='calculado':diagnosis='inconclusivo para inferência conjunta robusta: suporte limitado'
  evidence='sem evidência robusta após FDR'
  if v.q_global_acumulado_cluster_p<.05 or v.q_global_joint_cluster_p<.05:evidence='sensível à inferência; sem confirmação CR2/WCR após FDR'
  if v.coluna=='tipo_onda_de_frio' and v.periodo=='Pré':evidence='não robusto: resultado histórico pré não confirmado'
  rows.append(dict(periodo=v.periodo,coluna=v.coluna,exposicao=v.exposicao,diagnostico=diagnosis,evidencia=evidence,suporte=u.status,n_eff=u.n_eff,df_cr2_acumulado=cum.df,htz_disponivel=joint.status_inferencia=='calculado',cd_sinal_nominal=q.cd_p<.05,autocorr_sinal_nominal=q.autocorr_cluster_p<.05,placebo_wcr_bh=pl.q_global_joint_boot_p<.05))
 save(pd.DataFrame(rows),'classificacao_final')
